-- GENERATED by `python -m silver.render` from silver/spec.py. Do not edit by hand.
-- Safe to run repeatedly. {db} is the database name.

-- ---- one line per topic and reason: what was rejected and why ----
CREATE OR REPLACE VIEW {db}.QUARANTINE.reject_summary AS
SELECT 'ref.merchants' AS topic, reject_reason, COUNT(*) AS messages,
       MIN(loaded_at) AS first_loaded, MAX(loaded_at) AS last_loaded
FROM {db}.QUARANTINE.rejected_merchants GROUP BY reject_reason
UNION ALL
SELECT 'ref.accounts' AS topic, reject_reason, COUNT(*) AS messages,
       MIN(loaded_at) AS first_loaded, MAX(loaded_at) AS last_loaded
FROM {db}.QUARANTINE.rejected_accounts GROUP BY reject_reason
UNION ALL
SELECT 'payments.transactions' AS topic, reject_reason, COUNT(*) AS messages,
       MIN(loaded_at) AS first_loaded, MAX(loaded_at) AS last_loaded
FROM {db}.QUARANTINE.rejected_transactions GROUP BY reject_reason
UNION ALL
SELECT 'payments.refunds' AS topic, reject_reason, COUNT(*) AS messages,
       MIN(loaded_at) AS first_loaded, MAX(loaded_at) AS last_loaded
FROM {db}.QUARANTINE.rejected_refunds GROUP BY reject_reason
UNION ALL
SELECT 'payments.disputes' AS topic, reject_reason, COUNT(*) AS messages,
       MIN(loaded_at) AS first_loaded, MAX(loaded_at) AS last_loaded
FROM {db}.QUARANTINE.rejected_disputes GROUP BY reject_reason
UNION ALL
SELECT 'billing.fees' AS topic, reject_reason, COUNT(*) AS messages,
       MIN(loaded_at) AS first_loaded, MAX(loaded_at) AS last_loaded
FROM {db}.QUARANTINE.rejected_fees GROUP BY reject_reason
UNION ALL
SELECT 'ledger.adjustments' AS topic, reject_reason, COUNT(*) AS messages,
       MIN(loaded_at) AS first_loaded, MAX(loaded_at) AS last_loaded
FROM {db}.QUARANTINE.rejected_adjustments GROUP BY reject_reason;

-- Re-reads bronze and compares it with what the stream track produced. A stream that has
-- not run yet shows up as unaccounted rows, never as silence.
CREATE OR REPLACE VIEW {db}.OPS.recon_merchants AS
WITH parsed AS (
  SELECT
    IFF(TYPEOF(GET_PATH(raw, 'event_id')) = 'VARCHAR', GET_PATH(raw, 'event_id')::STRING, NULL) AS event_id,
    IFF(TYPEOF(GET_PATH(raw, 'event_type')) = 'VARCHAR', GET_PATH(raw, 'event_type')::STRING, NULL) AS event_type,
    IFF(TYPEOF(GET_PATH(raw, 'entity_id')) = 'VARCHAR', GET_PATH(raw, 'entity_id')::STRING, NULL) AS entity_id,
    IFF(TYPEOF(GET_PATH(raw, 'op')) = 'VARCHAR', GET_PATH(raw, 'op')::STRING, NULL) AS op,
    IFF(TYPEOF(GET_PATH(raw, 'schema_version')) = 'INTEGER', GET_PATH(raw, 'schema_version')::NUMBER, NULL) AS schema_version,
    IFF(TYPEOF(GET_PATH(raw, 'sequence')) = 'INTEGER', GET_PATH(raw, 'sequence')::NUMBER, NULL) AS sequence,
    TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'event_time')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'event_time')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS event_time,
    TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'emitted_at')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'emitted_at')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS emitted_at,
    IFF(TYPEOF(GET_PATH(raw, 'payload.merchant_id')) = 'VARCHAR', GET_PATH(raw, 'payload.merchant_id')::STRING, NULL) AS merchant_id,
    IFF(TYPEOF(GET_PATH(raw, 'payload.name')) = 'VARCHAR', GET_PATH(raw, 'payload.name')::STRING, NULL) AS name,
    IFF(TYPEOF(GET_PATH(raw, 'payload.country')) = 'VARCHAR', GET_PATH(raw, 'payload.country')::STRING, NULL) AS country,
    IFF(TYPEOF(GET_PATH(raw, 'payload.vertical')) = 'VARCHAR', GET_PATH(raw, 'payload.vertical')::STRING, NULL) AS vertical,
    IFF(TYPEOF(GET_PATH(raw, 'payload.risk_status')) = 'VARCHAR', GET_PATH(raw, 'payload.risk_status')::STRING, NULL) AS risk_status,
    raw,
    source_file,
    source_row,
    loaded_at
  FROM {db}.BRONZE.ref_merchants
),
checked AS (
  SELECT *,
    CASE
      WHEN event_id IS NULL THEN 'missing_event_id'
      WHEN event_type IS NULL THEN 'missing_event_type'
      WHEN entity_id IS NULL THEN 'missing_entity_id'
      WHEN event_time IS NULL THEN 'bad_type_event_time'
      WHEN emitted_at IS NULL THEN 'bad_type_emitted_at'
      WHEN schema_version IS NULL THEN 'bad_type_schema_version'
      WHEN sequence IS NULL THEN 'bad_type_sequence'
      WHEN schema_version NOT IN (1, 2) THEN 'unknown_schema_version'
      WHEN event_type NOT IN ('merchant_deleted', 'merchant_upserted') THEN 'unknown_event_type'
      WHEN COALESCE(op, '') NOT IN ('upsert', 'delete') THEN 'bad_op'
      WHEN merchant_id IS NULL THEN 'missing_payload_merchant_id'
      WHEN op = 'upsert' AND name IS NULL THEN 'missing_payload_name'
      WHEN op = 'upsert' AND country IS NULL THEN 'missing_payload_country'
      WHEN op = 'upsert' AND risk_status IS NULL THEN 'missing_payload_risk_status'
      WHEN op = 'upsert' AND risk_status NOT IN ('low', 'medium', 'high') THEN 'bad_value_risk_status'
    END AS reject_reason
  FROM parsed
)
SELECT 'ref.merchants' AS topic, (SELECT COUNT(*) FROM checked) AS bronze_rows,
  (SELECT COUNT(*) FROM {db}.QUARANTINE.rejected_merchants) AS rejected_rows, (SELECT COUNT(*) FROM checked WHERE reject_reason IS NULL) - (SELECT COUNT(*) FROM (SELECT DISTINCT merchant_id, sequence FROM checked WHERE reject_reason IS NULL) d) AS duplicate_rows, (SELECT COUNT(*) FROM {db}.SILVER.silver_merchants_versions) AS unique_valid_events,
  (SELECT COUNT(DISTINCT merchant_id) FROM checked WHERE reject_reason IS NULL) AS entities_expected, (SELECT COUNT(*) FROM {db}.SILVER.silver_merchants) AS entities_actual;

-- Re-reads bronze and compares it with what the stream track produced. A stream that has
-- not run yet shows up as unaccounted rows, never as silence.
CREATE OR REPLACE VIEW {db}.OPS.recon_accounts AS
WITH parsed AS (
  SELECT
    IFF(TYPEOF(GET_PATH(raw, 'event_id')) = 'VARCHAR', GET_PATH(raw, 'event_id')::STRING, NULL) AS event_id,
    IFF(TYPEOF(GET_PATH(raw, 'event_type')) = 'VARCHAR', GET_PATH(raw, 'event_type')::STRING, NULL) AS event_type,
    IFF(TYPEOF(GET_PATH(raw, 'entity_id')) = 'VARCHAR', GET_PATH(raw, 'entity_id')::STRING, NULL) AS entity_id,
    IFF(TYPEOF(GET_PATH(raw, 'op')) = 'VARCHAR', GET_PATH(raw, 'op')::STRING, NULL) AS op,
    IFF(TYPEOF(GET_PATH(raw, 'schema_version')) = 'INTEGER', GET_PATH(raw, 'schema_version')::NUMBER, NULL) AS schema_version,
    IFF(TYPEOF(GET_PATH(raw, 'sequence')) = 'INTEGER', GET_PATH(raw, 'sequence')::NUMBER, NULL) AS sequence,
    TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'event_time')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'event_time')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS event_time,
    TRY_TO_TIMESTAMP_NTZ(IFF(REGEXP_LIKE(GET_PATH(raw, 'emitted_at')::STRING, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z'), GET_PATH(raw, 'emitted_at')::STRING, NULL), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') AS emitted_at,
    IFF(TYPEOF(GET_PATH(raw, 'payload.account_id')) = 'VARCHAR', GET_PATH(raw, 'payload.account_id')::STRING, NULL) AS account_id,
    IFF(TYPEOF(GET_PATH(raw, 'payload.merchant_id')) = 'VARCHAR', GET_PATH(raw, 'payload.merchant_id')::STRING, NULL) AS merchant_id,
    IFF(TYPEOF(GET_PATH(raw, 'payload.label')) = 'VARCHAR', GET_PATH(raw, 'payload.label')::STRING, NULL) AS label,
    IFF(TYPEOF(GET_PATH(raw, 'payload.currency')) = 'VARCHAR', GET_PATH(raw, 'payload.currency')::STRING, NULL) AS currency,
    IFF(TYPEOF(GET_PATH(raw, 'payload.fee_plan')) = 'VARCHAR', GET_PATH(raw, 'payload.fee_plan')::STRING, NULL) AS fee_plan,
    IFF(TYPEOF(GET_PATH(raw, 'payload.payout_schedule')) = 'VARCHAR', GET_PATH(raw, 'payload.payout_schedule')::STRING, NULL) AS payout_schedule,
    IFF(TYPEOF(GET_PATH(raw, 'payload.status')) = 'VARCHAR', GET_PATH(raw, 'payload.status')::STRING, NULL) AS status,
    raw,
    source_file,
    source_row,
    loaded_at
  FROM {db}.BRONZE.ref_accounts
),
checked AS (
  SELECT *,
    CASE
      WHEN event_id IS NULL THEN 'missing_event_id'
      WHEN event_type IS NULL THEN 'missing_event_type'
      WHEN entity_id IS NULL THEN 'missing_entity_id'
      WHEN event_time IS NULL THEN 'bad_type_event_time'
      WHEN emitted_at IS NULL THEN 'bad_type_emitted_at'
      WHEN schema_version IS NULL THEN 'bad_type_schema_version'
      WHEN sequence IS NULL THEN 'bad_type_sequence'
      WHEN schema_version NOT IN (1, 2) THEN 'unknown_schema_version'
      WHEN event_type NOT IN ('account_deleted', 'account_upserted') THEN 'unknown_event_type'
      WHEN COALESCE(op, '') NOT IN ('upsert', 'delete') THEN 'bad_op'
      WHEN account_id IS NULL THEN 'missing_payload_account_id'
      WHEN op = 'upsert' AND merchant_id IS NULL THEN 'missing_payload_merchant_id'
      WHEN op = 'upsert' AND currency IS NULL THEN 'missing_payload_currency'
      WHEN op = 'upsert' AND fee_plan IS NULL THEN 'missing_payload_fee_plan'
      WHEN op = 'upsert' AND status IS NULL THEN 'missing_payload_status'
      WHEN op = 'upsert' AND currency NOT IN ('USD', 'EUR', 'GBP', 'CAD', 'AUD') THEN 'unknown_currency'
      WHEN op = 'upsert' AND fee_plan NOT IN ('standard', 'growth', 'enterprise') THEN 'bad_value_fee_plan'
      WHEN op = 'upsert' AND status NOT IN ('active', 'suspended', 'closed') THEN 'bad_value_status'
    END AS reject_reason
  FROM parsed
)
SELECT 'ref.accounts' AS topic, (SELECT COUNT(*) FROM checked) AS bronze_rows,
  (SELECT COUNT(*) FROM {db}.QUARANTINE.rejected_accounts) AS rejected_rows, (SELECT COUNT(*) FROM checked WHERE reject_reason IS NULL) - (SELECT COUNT(*) FROM (SELECT DISTINCT account_id, sequence FROM checked WHERE reject_reason IS NULL) d) AS duplicate_rows, (SELECT COUNT(*) FROM {db}.SILVER.silver_accounts_versions) AS unique_valid_events,
  (SELECT COUNT(DISTINCT account_id) FROM checked WHERE reject_reason IS NULL) AS entities_expected, (SELECT COUNT(*) FROM {db}.SILVER.silver_accounts) AS entities_actual;

CREATE OR REPLACE VIEW {db}.OPS.recon_transactions AS
SELECT 'payments.transactions' AS topic, (SELECT COUNT(*) FROM {db}.BRONZE.payments_transactions) AS bronze_rows,
  (SELECT COUNT(*) FROM {db}.QUARANTINE.rejected_transactions) AS rejected_rows, COUNT(CASE WHEN is_valid AND dup_rank > 1 THEN 1 END) AS duplicate_rows, COUNT(CASE WHEN is_valid AND dup_rank = 1 THEN 1 END) AS unique_valid_events,
  COUNT(DISTINCT CASE WHEN is_valid THEN transaction_id END) AS entities_expected, (SELECT COUNT(*) FROM {db}.SILVER.silver_transactions) AS entities_actual
FROM {db}.SILVER.typed_transactions;

CREATE OR REPLACE VIEW {db}.OPS.recon_refunds AS
SELECT 'payments.refunds' AS topic, (SELECT COUNT(*) FROM {db}.BRONZE.payments_refunds) AS bronze_rows,
  (SELECT COUNT(*) FROM {db}.QUARANTINE.rejected_refunds) AS rejected_rows, COUNT(CASE WHEN is_valid AND dup_rank > 1 THEN 1 END) AS duplicate_rows, COUNT(CASE WHEN is_valid AND dup_rank = 1 THEN 1 END) AS unique_valid_events,
  COUNT(DISTINCT CASE WHEN is_valid THEN refund_id END) AS entities_expected, (SELECT COUNT(*) FROM {db}.SILVER.silver_refunds) AS entities_actual
FROM {db}.SILVER.typed_refunds;

