CREATE OR REPLACE VIEW {db}.OPS.recon_fees AS
SELECT 'billing.fees' AS topic, (SELECT COUNT(*) FROM {db}.BRONZE.billing_fees) AS bronze_rows,
  (SELECT COUNT(*) FROM {db}.QUARANTINE.rejected_fees) AS rejected_rows, COUNT(CASE WHEN is_valid AND dup_rank > 1 THEN 1 END) AS duplicate_rows, COUNT(CASE WHEN is_valid AND dup_rank = 1 THEN 1 END) AS unique_valid_events,
  COUNT(DISTINCT CASE WHEN is_valid THEN fee_id END) AS entities_expected, (SELECT COUNT(*) FROM {db}.SILVER.silver_fees) AS entities_actual
