CREATE OR REPLACE VIEW {db}.OPS.recon_adjustments AS
SELECT 'ledger.adjustments' AS topic, (SELECT COUNT(*) FROM {db}.BRONZE.ledger_adjustments) AS bronze_rows,
  (SELECT COUNT(*) FROM {db}.QUARANTINE.rejected_adjustments) AS rejected_rows, COUNT(CASE WHEN is_valid AND dup_rank > 1 THEN 1 END) AS duplicate_rows, COUNT(CASE WHEN is_valid AND dup_rank = 1 THEN 1 END) AS unique_valid_events,
  COUNT(DISTINCT CASE WHEN is_valid THEN adjustment_id END) AS entities_expected, (SELECT COUNT(*) FROM {db}.SILVER.silver_adjustments) AS entities_actual
FROM {db}.SILVER.typed_adjustments;

-- ---- the no-silent-loss check: unaccounted_rows and missing_entities must be 0 ----
CREATE OR REPLACE VIEW {db}.OPS.silver_reconciliation AS
SELECT *,
       bronze_rows - rejected_rows - duplicate_rows - unique_valid_events AS unaccounted_rows,
       entities_expected - entities_actual AS missing_entities
FROM (
  SELECT * FROM {db}.OPS.recon_merchants
  UNION ALL
  SELECT * FROM {db}.OPS.recon_accounts
  UNION ALL
  SELECT * FROM {db}.OPS.recon_transactions
  UNION ALL
  SELECT * FROM {db}.OPS.recon_refunds
  UNION ALL
  SELECT * FROM {db}.OPS.recon_disputes
  UNION ALL
  SELECT * FROM {db}.OPS.recon_fees
  UNION ALL
  SELECT * FROM {db}.OPS.recon_adjustments
);
